get_shipping_settings.code:
import {shippingSettings} from 'webcommander-sdk';

const response = await shippingSettings.getShippingSettings(client);
const settings = response.map.shipping_settings;
console.log(settings.default_shipping_profile?.name, settings.default_delivery_profile?.name);
console.log(settings.enable_shipping_default_tax, settings.enable_delivery_default_tax);
console.log(settings.enable_shipping_class, settings.enable_flat_view_class);

patch_shipping_settings.code:
import {shippingSettings} from 'webcommander-sdk';

const response = await shippingSettings.patchShippingSettings(client, {
    shipping_settings: {enable_shipping_default_tax: true},
});
console.log(response.map.shipping_settings.enable_shipping_default_tax);

